export function InnerPage({slug}:{slug:string}){const{lang}=useLanguage();const c=configs[slug]||configs['learn'];return <><section className="topo bg-[#113a2f] py-24 text-white md:py-32"><div className="container"><p className="eyebrow">{c.kicker}</p><h1 className="mt-4 max-w-5xl text-[clamp(2.5rem,6vw,5rem)]">{t(lang,c.ka,c.en)}</h1><p className="mt-6 max-w-3xl text-lg text-white/70">{t(lang,c.dka,c.den)}</p></div></section>{slug.startsWith('history')?<History lang={lang} slug={slug}/>:slug.startsWith('learn')?<Learn lang={lang} slug={slug}/>:slug==='orienteering'?<Sport lang={lang}/>:slug==='federation'?<Federation lang={lang}/>:slug==='contact'?<Contact lang={lang}/>:<Library lang={lang} slug={slug}/>}</>}
function History({lang,slug}:{lang:'ka'|'en';slug:string}){if(slug==='history/maps'||slug==='history/people')return <Section><Empty icon={slug.endsWith('maps')?Map:Users} title={t(lang,'კოლექციის დამუშავება მიმდინარეობს','Collection in preparation')} text={t(lang,'ჩანაწერები გამოქვეყნდება მასალის მიღების, აღწერისა და წყაროს დადასტურების შემდეგ. მონაცემთა სტრუქტურა მზად არის ფოტოებისთვის, ბიოგრაფიებისთვის, რუკების ავტორებისა და ღონისძიებების მითითებისთვის.','Records will be published after material is received, catalogued and sourced. The data structure is ready for photographs, biographies, cartographers and event references.')}/></Section>;if(slug==='history/archive')return <Section><div className="grid gap-4 md:grid-cols-3">{['ძველი რუკები|Old maps','ისტორიული ფოტოები|Historical photographs','საქართველოს ჩემპიონატები|Georgian championships','საერთაშორისო მონაწილეობა|International participation','დოკუმენტები|Documents','სტატიები და მოგონებები|Articles and memories'].map(x=>{let[a,b]=x.split('|');return <div className="card" key={b}><Archive className="text-orange-600"/><h3 className="mt-8 text-xl">{t(lang,a,b)}</h3><p className="mt-3 text-sm text-slate-500">{t(lang,'კატალოგი მზადდება — ფაქტობრივი მასალა ჯერ არ არის გამოქვეყნებული.','Catalogue in preparation—no factual material is published yet.')}</p></div>})}</div></Section>;return <Section><div className="mb-12 flex flex-wrap gap-3"><Link className="btn bg-[#123d31] text-white" href="/history/timeline">{t(lang,'ქრონოლოგია','Timeline')}</Link><Link className="btn border" href="/history/maps">{t(lang,'რუკები','Maps')}</Link><Link className="btn border" href="/history/people">{t(lang,'ადამიანები','People')}</Link><Link className="btn border" href="/history/archive">{t(lang,'არქივი','Archive')}</Link></div><div className="max-w-4xl">{history.map((x,i)=><article className="relative border-l-2 border-orange-500 pb-14 pl-10" key={x.id}><span className="absolute -left-[9px] top-0 h-4 w-4 rounded-full bg-orange-500"/><span className="rounded-full bg-orange-50 px-3 py-1 text-xs font-bold text-orange-700">{t(lang,'გადასამოწმებელი ჩანაწერი','Awaiting verification')}</span><h2 className="mt-5 !text-3xl">{t(lang,x.titleKa,x.titleEn)}</h2><p className="mt-4 text-slate-600">{t(lang,x.descriptionKa,x.descriptionEn)}</p><p className="mt-4 text-xs font-bold text-slate-400">{t(lang,'წყაროები ჯერ არ არის დართული','No sources attached yet')}</p></article>)}</div></Section>}
function Learn({lang,slug}:{lang:'ka'|'en';slug:string}){const chosen=lessons.find(x=>slug.endsWith(x.slug));return <Section>{chosen&&<div className="mb-12 rounded-2xl bg-[#f5f3eb] p-8"><span className="eyebrow">LEVEL {chosen.level}</span><h2 className="mt-3 !text-3xl">{t(lang,chosen.titleKa,chosen.titleEn)}</h2><div className="mt-7 grid gap-3 md:grid-cols-3">{(lang==='ka'?chosen.contentKa:chosen.contentEn).map(x=><div className="flex gap-2" key={x}><CheckCircle2 className="text-orange-600"/><span>{x}</span></div>)}</div></div>}<div className="grid gap-4 md:grid-cols-5">{lessons.map(x=><Link href={`/learn/${x.slug}`} className="card" key={x.id}><div className="control mb-5">{x.level}</div><h3>{t(lang,x.titleKa,x.titleEn)}</h3><p className="mt-3 text-sm text-slate-500">{t(lang,x.summaryKa,x.summaryEn)}</p></Link>)}</div>{slug==='learn/controls'&&<div className="mt-14 overflow-hidden rounded-xl border"><div className="grid grid-cols-5 bg-[#123d31] p-4 text-sm text-white"><b>#</b><b>{t(lang,'კოდი','Code')}</b><b>{t(lang,'ობიექტი','Feature')}</b><b>{t(lang,'მდებარეობა','Location')}</b><b>{t(lang,'დამატებით','Additional')}</b></div><div className="p-8 text-center text-slate-500">{t(lang,'ოფიციალური სასწავლო მასალის ჩასასმელი კომპონენტი','Component ready for official educational material')}</div></div>}</Section>}
function Sport({lang}:{lang:'ka'|'en'}){return <><Section><div className="grid gap-5 md:grid-cols-3">{[['რუკა','Map','გარემოს ზუსტი, სპეციალური გამოსახულება.','A precise, specialised representation of terrain.'],['კომპასი','Compass','გეხმარება მიმართულებისა და ჩრდილოეთის განსაზღვრაში.','Helps identify direction and north.'],['პუნქტები','Controls','მარშრუტზე მოსანახულებელი მონიშნული ადგილები.','Marked places to visit along the course.'],['სტარტი და ფინიში','Start and finish','სამკუთხედი იწყებს, ორმაგი წრე ასრულებს მარშრუტს.','A triangle begins and a double circle ends the course.'],['მარშრუტის არჩევა','Route choice','ყველა მონაწილე საკუთარ გზას ირჩევს.','Every participant chooses their own way.'],['უსაფრთხოება','Safety','მომზადება და ორგანიზატორის მითითებები ყოველთვის პრიორიტეტია.','Preparation and organiser guidance always come first.']].map(x=><div className="card" key={x[1]}><Flag className="text-orange-600"/><h3 className="mt-6 text-xl">{t(lang,x[0],x[1])}</h3><p className="mt-3 text-slate-500">{t(lang,x[2],x[3])}</p></div>)}</div></Section><Section className="bg-[#f5f3eb]"><h2>{t(lang,'დისციპლინები','Disciplines')}</h2><p className="mt-4 text-slate-600">{t(lang,'ძირითადი საგანმანათლებლო აქცენტი — ფეხით ორიენტირება.','The main educational focus is Foot Orienteering.')}</p><div className="mt-10 grid gap-3 sm:grid-cols-2 md:grid-cols-4">{discipline.map(x=><div className="card" key={x[0]}><Mountain className="text-orange-600"/><b className="mt-5 block">{t(lang,x[1],x[0])}</b></div>)}</div></Section></>}
function Federation({lang}:{lang:'ka'|'en'}){return <><Section><div className="grid gap-10 md:grid-cols-3">{[['ვინ ვართ','Who we are','ფედერაცია ქმნის ღია, სანდო და საგანმანათლებლო სივრცეს სპორტის განვითარებისთვის.','The federation is creating an open, trusted educational home for the sport.'],['ჩვენი მიზანი','Our goal','ორიენტირების თანმიმდევრული განვითარება საქართველოს მასშტაბით.','Consistent development of orienteering across Georgia.'],['ჩვენი მისია','Our mission','მემკვიდრეობის დაცვა, ახალი თაობის სწავლება და ძლიერი საზოგადოების შექმნა.','Preserve the legacy, teach a new generation and build a strong community.']].map(x=><div key={x[1]}><h2 className="!text-3xl">{t(lang,x[0],x[1])}</h2><p className="mt-4 text-slate-600">{t(lang,x[2],x[3])}</p></div>)}</div></Section><Section className="bg-[#f5f3eb]"><h2>{t(lang,'საქმიანობის მიმართულებები','Areas of work')}</h2><div className="mt-9 grid gap-4 md:grid-cols-4">{['სპორტის განვითარება|Sport development','ახალგაზრდები და სკოლები|Youth and schools','სწავლება|Education','რუკების შექმნა|Mapmaking','შეჯიბრებები|Competitions','ისტორიული მემკვიდრეობა|Historical legacy','საერთაშორისო თანამშრომლობა|International cooperation'].map(x=>{let[a,b]=x.split('|');return <div className="card" key={b}><Compass className="text-orange-600"/><b className="mt-6 block">{t(lang,a,b)}</b></div>})}</div><div className="mt-14"><h2 className="!text-3xl">{t(lang,'ხელმძღვანელობა და სტრუქტურა','Leadership and structure')}</h2><Empty icon={Users} title={t(lang,'ინფორმაცია მზადდება','Information in preparation')} text={t(lang,'სახელები და ბიოგრაფიები გამოქვეყნდება მხოლოდ ოფიციალური დადასტურების შემდეგ.','Names and biographies will be published only after official confirmation.')}/></div></Section></>}
function Library({lang,slug}:{lang:'ka'|'en';slug:string}){const isActivity=slug==='activities',isNews=slug==='news';if(isActivity||isNews)return <Section><Empty icon={isActivity?Clock:BookOpen} title={t(lang,isActivity?'ახალი აქტივობები მალე გამოქვეყნდება':'სიახლეების არქივი მზადდება',isActivity?'New activities coming soon':'News archive in preparation')} text={t(lang,isActivity?'არ ვქმნით გამოგონილ ღონისძიებებს. გადამოწმებული ვარჯიშები და შეხვედრები გამოქვეყნებისთანავე აქ გამოჩნდება.':'ფედერაციის გადამოწმებული განცხადებები და მასალები გამოქვეყნებისთანავე აქ გამოჩნდება.',isActivity?'We do not create fictional events. Verified training and meetings will appear here as they are announced.':'Verified federation announcements and materials will appear here as published.')}/></Section>;let items=slug==='documents'?['წესდება|Statute','ოქმები|Minutes','რეგულაციები|Regulations','ოფიციალური განცხადებები|Official announcements','განვითარების გეგმები|Development plans','წლიური ანგარიშები|Annual reports']:['სასწავლო მასალები|Learning materials','რუკები|Maps','ისტორიული მასალები|Historical materials','ოფიციალური დოკუმენტები|Official documents','სასარგებლო ბმულები|Useful links','ვიდეოები|Videos','სახელმძღვანელოები|Guides'];return <Section><div className="grid gap-4 md:grid-cols-3">{items.map(x=>{let[a,b]=x.split('|');return <div className="card" key={b}><FileText className="text-orange-600"/><h3 className="mt-8 text-xl">{t(lang,a,b)}</h3><p className="mt-3 text-sm text-slate-500">{t(lang,'მასალა დაემატება გამოქვეყნების შემდეგ.','Material will appear when published.')}</p><span className="mt-6 inline-flex items-center gap-2 text-xs font-bold text-slate-400"><Download size={14}/> {t(lang,'ჯერ არ არის ფაილები','No files yet')}</span></div>})}</div></Section>}
function Contact({lang}:{lang:'ka'|'en'}){return <Section><div className="grid gap-14 md:grid-cols-2"><div><h2 className="!text-3xl">{t(lang,'საკონტაქტო ინფორმაცია','Contact information')}</h2><dl className="mt-8 grid gap-5"><div><dt className="text-xs font-bold text-slate-400">FEDERATION</dt><dd>{t(lang,'საქართველოს სპორტული ორიენტირების ეროვნული ფედერაცია','Georgian National Orienteering Federation')}</dd></div>{['ADDRESS','EMAIL','TELEPHONE','FACEBOOK · INSTAGRAM · YOUTUBE'].map(x=><div key={x}><dt className="text-xs font-bold text-slate-400">{x}</dt><dd className="text-slate-500">{t(lang,'ინფორმაცია დასამატებელია','To be configured')}</dd></div>)}</dl></div><form className="card" onSubmit={e=>e.preventDefault()}><div className="grid gap-5"><label>{t(lang,'სახელი','Name')}<input name="name" required/></label><label>{t(lang,'ელფოსტა','Email')}<input name="email" type="email" required/></label><label>{t(lang,'თემა','Subject')}<input name="subject" required/></label><label>{t(lang,'შეტყობინება','Message')}<textarea name="message" rows={5} required/></label><button className="btn btn-primary w-fit" type="submit">{t(lang,'გაგზავნა','Send')} <ArrowRight size={16}/></button><small className="text-slate-400">{t(lang,'ფორმის გაგზავნის სერვისი განვითარების შემდეგ ეტაპზე ჩაერთვება.','Form delivery will be connected in the next development phase.')}</small></div></form></div></Section>}
function Empty({icon:I,title,text}:{icon:typeof Archive;title:string;text:string}){return <div className="mt-8 rounded-2xl border border-dashed border-slate-300 bg-[#f8faf8] p-10 text-center"><I className="mx-auto text-orange-600" size={42}/><h3 className="mt-5 text-xl">{title}</h3><p className="mx-auto mt-3 max-w-2xl text-slate-500">{text}</p></div>}
